mapper.select:


    r.del_flag = '0'

        and r.request_no like concat('%', #{requestNo}, '%')


        and r.person_name like concat('%', #{personName}, '%')


        and r.matter_type = #{matterType}


        and r.person_id = #{personId}


        and r.status = #{status}


        and r.suggest_result = #{suggestResult}


        and r.final_result = #{finalResult}


        and date_format(r.receive_date, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')


        and date_format(r.receive_date, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')


order by
    case when r.status in ('2','3') then 1 else 0 end,
    case when r.receive_date is null or r.deadline_days is null then 2
         when date_add(r.receive_date, interval r.deadline_days day) < curdate() then 0
         else 1 end,
    r.create_time desc

mapper.update:
update jc_reply_request
matter_desc = #{matterDesc}, apply_dept = #{applyDept}, apply_contact = #{applyContact}, apply_doc_no = #{applyDocNo}, receive_date = #{receiveDate}, deadline_days = #{deadlineDays}, matter_type = #{matterType}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where request_id = #{requestId}

update jc_reply_request
set warn_level = #{warnLevel}, update_by = 'system', update_time = sysdate()
where request_id = #{requestId}
